SELECT COUNT(*)
FROM dish
WHERE shop_id = #{shopId}

    AND category_id = #{categoryId}


    AND dish_name LIKE CONCAT('%', #{dishName}, '%')


    AND status = #{status}

SELECT id, shop_id AS shopId, category_id AS categoryId, dish_name AS dishName, price, image_url AS imageUrl, description, stock, status, create_time AS createTime, update_time AS updateTime FROM dish WHERE shop_id = #{shopId}
AND category_id = #{categoryId}
AND dish_name LIKE CONCAT('%', #{dishName}, '%')
AND status = #{status}
ORDER BY id DESC LIMIT #{pageSize} OFFSET #{offset}

SELECT d.id, d.shop_id AS shopId, d.category_id AS categoryId, d.dish_name AS dishName, d.price, d.image_url AS imageUrl, d.description, d.stock, d.status, d.create_time AS createTime, d.update_time AS updateTime FROM dish d INNER JOIN merchant_shop s ON d.shop_id = s.id WHERE d.shop_id = #{shopId} AND d.status = 1 AND s.business_status = 1
AND d.category_id = #{categoryId}
ORDER BY d.id DESC
